,p_name=>'PE.PROPERTY.ACTION_CONDITION_JS_EXPRESSION_BOOLEAN.EXAMPLES'
,p_message_language=>'es'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Para volver correctamente cuando el empleado est\00E1 en el departamento 30 o es un gestor:</dt>'),
'<dd><pre>',
'( apex.env.P2_DEPTNO === "30" || apex.env.P2_JOB === "MANAGER" )',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564272
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(107844314206662646)
,p_name=>'PE.PROPERTY.ACTION_CONDITION_JS_EXPRESSION_BOOLEAN.PROMPT'
,p_message_language=>'es'
,p_message_text=>unistr('Expresi\00F3n JavaScript')
,p_version_scn=>2564296
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(107646139532662586)
,p_name=>'PE.PROPERTY.ACTION_CONDITION_JS_FUNC_BODY_BOOLEAN.EXAMPLES'
,p_message_language=>'es'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Para devolver correctamente cuando el empleado est\00E9 en el departamento 30:</dt>'),
'<dd><pre>',
'let deptno,',
'    rows;',
'',
'rows = apex.conn.execute( "select deptno from emp empno = :1", [ apex.env.P2_EMPNO ] ).rows;',
'for (let row of rows) {',
'  deptno = row.DEPTNO;',
'}',
