,p_name=>'PE.PROPERTY.BREAK_BEFORE_ROW.HELP'
,p_message_language=>'es'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Defina el marcador HTML utilizado en el elemento de fila de divisi\00F3n de control. Las etiquetas que se abran aqu\00ED deber\00E1n cerrarse m\00E1s tarde en el atributo <b>Despu\00E9s de fila</b> a continuaci\00F3n a fin de formar un contenedor para el elemento de salto d')
||unistr('e columna definido en el atributo <b>Formato de divisi\00F3n de columna</b>.'),
'<br>',
'Ejemplo:',
'<ul>',
'<li>Antes de fila: <code>&lt;tr style="border: 2px red solid" &gt;</code> </li>',
unistr('<li>Formato de divisi\00F3n de columna: <code> &lt;td&gt; #COLUMN_VALUE# &lt;/td&gt; </code> </li>'),
unistr('<li>Despu\00E9s de fila: <code>&lt;/tr&gt;</code> </li>')))
,p_version_scn=>2564319
);
