,p_version_scn=>2564298
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(107861359166662651)
,p_name=>'PE.PROPERTY.ICON_VIEW_CUSTOM.HELP'
,p_message_language=>'es'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Introduzca el HTML de columna personalizado para la vista de iconos.</p>',
unistr('<p>Est\00E1n disponibles las siguientes cadenas de sustituci\00F3n:'),
'<ul>',
unistr('<li><code>&&lt;COLUMN_NAME&gt;.</code>: cadenas de sustituci\00F3n para los nombres de columna.</li>'),
unistr('<li><code>&&lt;COLUMN_NAME&gt;_LABEL.</code>: cadenas de sustituci\00F3n para las etiquetas de columna.</li>'),
'<li><code>&APEX$ROW_ID.</code>: identificador de registro de la fila.</li>',
unistr('<li><code>&APEX$ROW_INDEX.</code>: n\00FAmero de secuencia de visualizaci\00F3n de registro.</li>'),
'<li><code>&APEX$ROW_URL.</code>: referencia al destino del enlace especificado.</li>',
'<li><code>&APEX$ROW_STATE_CLASSES.</code>: estado del registro, como <code>is-inserted</code> o <code>is-deleted</code>.</li>',
'</ul>',
'</p>'))
,p_version_scn=>2564298
);
