,p_name=>'PE.PROPERTY.LANDMARK_TYPE.LOV.COMPLEMENTARY.HELP'
,p_message_language=>'es'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>Una marca <code>complimentary</code> es una secci\00F3n de apoyo de una p\00E1gina dise\00F1ada para ser el valor <code>complimentary</code> del contenido'),
unistr('principal a un nivel similar al de la jerarqu\00EDa de DOM, pero significativa si se separa del contenido principal.</p>'),
''))
,p_version_scn=>2564177
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106956816734662380)
,p_name=>'PE.PROPERTY.LANDMARK_TYPE.LOV.CONTENTINFO.D'
,p_message_language=>'es'
,p_message_text=>unistr('Informaci\00F3n de Contenido')
