,p_name=>'PE.PROPERTY.SOURCE_JS_CODE.EXAMPLES'
,p_message_language=>'es'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>Incrementa en un 3% el salario de aquellos empleados cualificados para un aumento salarial:</dt>',
'<dd><pre>',
'let rows;',
'',
'function needsSalaryRaise( empno ) {',
unistr('    // marcador de posici\00F3n para alguna l\00F3gica complicada para calcular si el empleado necesita un aumento'),
'    return true;',
'}',
'',
'rows = apex.conn.execute( "select empno from emp where deptno = :deptno", { deptno: apex.env.P2_DEPTNO } ).rows;',
'for ( let row of rows ) {',
'    if ( needsSalaryRaise( row.EMPNO )) {',
'      apex.conn.execute( "update emp set sal = sal * 1.03 where empno = :empno", { empno: row.EMPNO } );',
'    }',
'}',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564272
);
