wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(108439551438662824)
,p_name=>'PE.PROPERTY.WHEN_NO_DATA_FOUND_MESSAGE.COMPONENT_PROPERTY.JET_CHART.HELP'
,p_message_language=>'es'
,p_message_text=>unistr('Introduzca el mensaje de texto que desea que se muestre si la consulta del gr\00E1fico no devuelve ninguna fila. Si se deja en blanco, Oracle JET utilizar\00E1 autom\00E1ticamente el mensaje por defecto "No hay datos para mostrar".')
,p_version_scn=>2564375
);
wwv_flow_imp_shared.create_message(
