wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(107085552961662419)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.CHK_COOKIE1'
,p_message_language=>'es'
,p_message_text=>unistr('Si utiliza la l\00F3gica incorporada, compruebe la cookie denominada [%0]. Si existe la cookie y su valor descodificado busca una fila en la tabla de sesiones internas, considere la sesi\00F3n v\00E1lida.')
,p_version_scn=>2564193
);
