'        {if ?CUSTOM_01/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_01.&lt;/span&gt;{endif/}',
'        {if ?CUSTOM_02/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_02.&lt;/span&gt;{endif/}',
