,p_return_value=>'DYNAMIC_ACTION'
,p_help_text=>unistr('<p>La geocodificaci\00F3n debe dispararse agregando la acci\00F3n din\00E1mica <em>Disparar geocodificaci\00F3n</em> para la p\00E1gina.</p>')
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1728803167561342.4412)
