'    for i in 1 .. l_file_names.count loop',
'        select *',
'          into l_file',
'          from apex_application_temp_files',
'         where name = l_file_names(i);',
unistr('        -- agregar aqu\00ED c\00F3digo para almacenar el archivo cargado en su propia tabla'),
'    end loop;',
'end;',
'</pre>'))
);
