);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(708300825765129776.4412)
,p_plugin_id=>wwv_flow_imp.id(707764939992010930.4412)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_prompt=>unistr('Funci\00F3n de Edici\00F3n de Nombre de Usuario de LDAP')
,p_attribute_type=>'PLSQL FUNCTION BODY'
,p_is_required=>false
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Puede proporcionar m\00E1s c\00F3digo para su ejecuci\00F3n y transformar el nombre de usuario en un formato perfectamente adaptado a la entrada de directorio LDAP o al nombre de usuario LDAP.'),
'La variable de enlace :USERNAME contiene el nombre especificado por el usuario final.',
unistr('Por ejemplo, el siguiente c\00F3digo llama a una funci\00F3n que sustituye todos los "."'' por "_"'' en la cadena DN:</p>'),
'',
'<p><pre>',
'return apex_custom_auth.ldap_dnprep(p_username => :USERNAME);',
'</pre></p>',
'',
unistr('<p>&PRODUCT_NAME. identificar\00E1 el nombre de usuario devuelto en el atributo de autenticaci\00F3n <strong>Escape de Nombre de Usuario</strong>.')))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(38288205752186126.4412)
,p_plugin_id=>wwv_flow_imp.id(707764939992010930.4412)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>8
,p_display_sequence=>80
,p_prompt=>unistr('Identificaci\00F3n de Nombre de Usuario')
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'STD'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Antes de sustituir <strong>%LDAP_USER%</strong> en el nombre distintivo de LDAP y en la cadena de b\00FAsqueda,'),
unistr('&PRODUCT_NAME. puede omitir autom\00E1ticamente caracteres especiales del nombre de usuario.'),
'<p/>',
unistr('Las posibles reglas para la identificaci\00F3n son:'),
'<ul>',
unistr('<li><strong>Est\00E1ndar</strong>:'),
unistr('Identifica caracteres especiales seg\00FAn la RFC 4514 (para nombres distintivos) y la RFC 4515 (para las cadenas de b\00FAsqueda).'),
unistr('Adem\00E1s, identifica los caracteres unicode.'),
unistr('\00C9ste es el valor m\00E1s seguro, pero puede provocar problemas con algunos servidores LDAP.</li>'),
unistr('<li><strong>S\00F3lo caracteres especiales</strong>:'),
unistr('Identifica caracteres especiales seg\00FAn la RFC 4514 (para nombres distintivos) y la RFC 4515 (para cadenas de b\00FAsqueda).'),
'No omite caracteres unicode.</li>',
unistr('<li><strong>Sin Identificaci\00F3n</strong>:'),
unistr('No identifica ning\00FAn car\00E1cter.'),
'Este valor es potencialmente inseguro,',
unistr('a menos que se utilice una <strong>Funci\00F3n de Edici\00F3n de Nombre de Usuario</strong> que ya'),
'identifique el nombre de usuario (por ejemplo, con apex_escape.ldap_dn o apex_escape.ldap_search_filter).</li>',
'</ul>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(38288513717188434.4412)
,p_plugin_attribute_id=>wwv_flow_imp.id(38288205752186126.4412)
,p_display_sequence=>10
,p_display_value=>unistr('Est\00E1ndar')
,p_return_value=>'STD'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(38288919604190164.4412)
,p_plugin_attribute_id=>wwv_flow_imp.id(38288205752186126.4412)
,p_display_sequence=>20
,p_display_value=>unistr('S\00F3lo caracteres especiales')
,p_return_value=>'ONLY'
);
