'select *',
'  from apex_application_temp_files',
unistr(' where name = :<em>nombre del elemento de p\00E1gina</em>;'),
'</pre>',
unistr('<p>Para acceder a los archivos si <strong>Permitir m\00FAltiples archivos</strong> est\00E1 definido en <strong>Yes</strong>:</p>'),
'<pre>',
'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'begin',
'    l_file_names := apex_string.split (',
unistr('                        p_str => :<em>nombre del elemento de p\00E1gina</em>,'),
'                        p_sep => '':'' );',
'    for i in 1 .. l_file_names.count loop',
