 p_id=>wwv_flow_imp.id(845153088232834479.4412)
,p_plugin_id=>wwv_flow_imp.id(1800066898109169760.4412)
,p_name=>'LOV'
,p_sql_min_column_count=>1
,p_sql_max_column_count=>2
,p_depending_on_has_to_exist=>true
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'<dt>Lista de valores basada en consulta SQL</dt>',
'<dd><pre>',
'select ename as d, ',
'       empno as r',
'  from emp ',
' order by 1',
'</pre></dd>',
unistr('<dt>Lista de valores con el mismo valor de retorno y visualizaci\00F3n</dt>'),
'<dd><pre>',
'select ename d,',
'       ename r ',
'  from emp ',
' order by 1',
'</pre>',
unistr('<p>Nota: al seleccionar la misma columna para los valores de retorno y visualizaci\00F3n, utilice un alias de columna.</p>'),
'</dd>',
'<dt>Lista de valores con variable de enlace</dt>',
'<dd><pre>',
'select ename,',
'       empno ',
'  from emp ',
' where deptno = :P3_DEPTNO ',
' order by 1',
'</pre>',
unistr('<p>Nota: defina el atributo <em>Elementos Principales de Lista de Valores en Cascada</em> en <code>P3_DEPTNO</code> si <code>P3_DEPTNO</code> es un elemento de p\00E1gina modificable en la misma p\00E1gina.</dd>'),
'</dl>'))
);
